"""Phase E1 - descriptor-set staleness check (Pillar 2, the item flagged in
README's "Further plans" as "originally planned item 4, never run").

Phases F1/F3/F4 test whether CLIP's *image-text alignment* holds up for a
domain outside its training distribution, using text prompts we hand-wrote
ourselves ("a Midjourney-generated image of a {}."). They do NOT test the
separate, narrower question: does LanCE's own frozen descriptor pool -
`prompts/prompt200new.py`'s 204 phrases, generated once by GPT-3.5-turbo
before training and never revisited - contain anything resembling an
AI-generated-image domain at all? GPT-3.5-turbo's training data has a
cutoff around September 2021; Stable Diffusion 2.1/XL/3, DALL-E 3, and
Midjourney v6 (the five generators Phase F3 used) all shipped after that,
so GPT-3.5 could not have named them when the pool was generated.

This script does not call any LLM (no API key/cost needed) - it inspects
the actual, already-generated, already-deployed descriptor pool that every
phase in this project trains against, which is a more faithful test than a
fresh API call: it is the literal artifact LanCE ships, not a new sample
that could differ by model snapshot or sampling temperature.
"""
import os
import sys
import json
import re

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from prompts.prompt200new import source_text_prompts, target_text_prompts

RESULTS_DIR = os.path.join(
    os.path.dirname(os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))),
    "results",
)

# Terms that would directly name the AI-generated-image domain (what we're
# checking is ABSENT from the pool).
DIRECT_AI_TERMS = [
    "ai-generated", "ai generated", "artificial intelligence",
    "stable diffusion", "dall-e", "dall e", "dalle", "midjourney",
    "diffusion model", "text-to-image", "text to image", "generative adversarial",
    r"\bgan\b", "deepfake", "neural network generated", "machine-generated",
    "synthetic image", "synthetically generated", "generated by ai",
    "diffusion-generated",
]

# Loosely related terms already in the pool - conceptually adjacent
# ("digital"/"computer-made") but not the same domain as photorealistic
# AI-generated imagery mimicking real photographs, which is what this
# dataset's generators (and the real-vs-fake framing) are actually about.
ADJACENT_TERMS = [
    "digital art", "cgi render", "vector graphic", "vr model",
    "hologram", "sci-fi", "futuristic concept art", "cyberpunk",
    "3d hologram", "augmented reality",
]


def find_matches(pool, terms):
    hits = {}
    for term in terms:
        pattern = term
        matched = [p for p in pool if re.search(pattern, p.lower())]
        if matched:
            hits[term] = matched
    return hits


def main():
    pool = target_text_prompts
    print(f"Frozen descriptor pool: {len(pool)} entries (source prompt: {source_text_prompts})")

    direct_hits = find_matches(pool, DIRECT_AI_TERMS)
    adjacent_hits = find_matches(pool, ADJACENT_TERMS)

    print(f"\nDirect AI-generation term matches: {len(direct_hits)}")
    for term, matched in direct_hits.items():
        print(f"  '{term}': {matched}")

    print(f"\nAdjacent/conceptually-nearby term matches: {len(adjacent_hits)}")
    for term, matched in adjacent_hits.items():
        print(f"  '{term}': {matched}")

    # The 5 specific generators Phase F3 tested against, with release dates,
    # checked individually for a name match.
    generators = {
        "Stable Diffusion 2.1": "Dec 2022",
        "Stable Diffusion XL": "Jul 2023",
        "Stable Diffusion 3": "2024",
        "DALL-E 3": "Oct 2023",
        "Midjourney v6": "Dec 2023",
    }
    gpt35_cutoff = "~Sept 2021"
    generator_check = {}
    for gen_name, release in generators.items():
        key_term = gen_name.split()[0].lower()  # "stable"/"dall-e"/"midjourney"
        found = any(key_term in p.lower() for p in pool)
        generator_check[gen_name] = {"released": release, "named_in_pool": found}
        print(f"  {gen_name} (released {release}, {'after' if True else ''} GPT-3.5 cutoff {gpt35_cutoff}): "
              f"{'FOUND' if found else 'not found'} in pool")

    results = {
        "pool_size": len(pool),
        "source_text_prompts": source_text_prompts,
        "gpt35_training_cutoff_approx": gpt35_cutoff,
        "direct_ai_term_matches": direct_hits,
        "n_direct_ai_term_matches": len(direct_hits),
        "adjacent_term_matches": adjacent_hits,
        "n_adjacent_term_matches": len(adjacent_hits),
        "generator_specific_check": generator_check,
        "n_generators_named": sum(1 for v in generator_check.values() if v["named_in_pool"]),
        "n_generators_checked": len(generators),
    }
    os.makedirs(RESULTS_DIR, exist_ok=True)
    out_path = os.path.join(RESULTS_DIR, "phase_e1_results.json")
    with open(out_path, "w") as f:
        json.dump(results, f, indent=2)
    print(f"\nWrote {out_path}")
    print(f"\nSummary: {len(direct_hits)}/{ len(DIRECT_AI_TERMS)} direct AI-generation terms found in the pool; "
          f"{results['n_generators_named']}/{results['n_generators_checked']} of Phase F3's specific generators named.")


if __name__ == "__main__":
    main()
